"use client";

import { useTranslations } from "next-intl";
import { useState } from "react";

import { bff } from "@/lib/bff";
import { ui } from "@/lib/ui";

/** Shapes of /api/v1/accounting/datev-mappings (A36, M18-01). Local types, the generated
 *  api-client is not regenerated by this task. */
export type DatevMapping = {
  id: string;
  ledger_id: string | null;
  account_code: string;
  datev_account: string;
  label: string | null;
  active: boolean;
  valid_from: string | null;
};

export type LedgerOption = { id: string; name: string };

export type ImportRow = {
  line_no: number;
  account_code: string | null;
  datev_account: string | null;
  label: string | null;
  valid_from: string | null;
  action: "create" | "update" | "unchanged" | "error";
  error: string | null;
  existing_datev_account: string | null;
};

export type ImportResult = {
  dry_run: boolean;
  ledger_id: string | null;
  rows: ImportRow[];
  file_errors: string[];
  counts: Record<string, number>;
};

export type ReportLine = {
  account_id: string;
  account_code: string;
  account_name: string;
  datev_account: string | null;
  lines_in_period: number;
  first_booking_date: string | null;
  last_booking_date: string | null;
  unmapped: boolean;
  unmapped_lines: number;
  reason: string | null;
};

export type Report = {
  ledger_id: string;
  period_from: string;
  period_to: string;
  unmapped_count: number;
  used_unmapped_count: number;
  accounts: ReportLine[];
};

const BASE = "/api/bff/accounting/datev-mappings";

function formatDate(iso: string | null): string {
  if (!iso) return "";
  const [y, m, d] = iso.split("-");
  return `${d}.${m}.${y}`;
}

function ledgerName(ledgers: LedgerOption[], id: string | null, all: string): string {
  if (!id) return all;
  return ledgers.find((l) => l.id === id)?.name ?? id;
}

export function DatevMappingsAdmin({
  initial,
  ledgers,
  canManage,
}: {
  initial: DatevMapping[];
  ledgers: LedgerOption[];
  canManage: boolean;
}) {
  const t = useTranslations("DatevMappings");
  const [rows, setRows] = useState<DatevMapping[]>(initial);
  const [error, setError] = useState<string | null>(null);
  const [message, setMessage] = useState<string | null>(null);
  const [busy, setBusy] = useState(false);

  // Anlegen
  const [form, setForm] = useState({ account_code: "", datev_account: "", label: "", ledger_id: "", valid_from: "" });

  // Import
  const [csv, setCsv] = useState("");
  const [importLedger, setImportLedger] = useState("");
  const [preview, setPreview] = useState<ImportResult | null>(null);

  // Prüfbericht
  const year = new Date().getFullYear();
  const [reportLedger, setReportLedger] = useState(ledgers[0]?.id ?? "");
  const [start, setStart] = useState(`${year}-01-01`);
  const [end, setEnd] = useState(`${year}-12-31`);
  const [report, setReport] = useState<Report | null>(null);
  const [onlyUnmapped, setOnlyUnmapped] = useState(true);

  async function reload() {
    const res = await bff<DatevMapping[]>(`${BASE}?include_inactive=true`);
    if (res.ok) setRows(res.data);
  }

  async function create(event: React.FormEvent) {
    event.preventDefault();
    setBusy(true);
    setError(null);
    setMessage(null);
    const res = await bff<DatevMapping>(BASE, {
      method: "POST",
      body: JSON.stringify({
        account_code: form.account_code.trim(),
        datev_account: form.datev_account.trim(),
        label: form.label.trim() || null,
        ledger_id: form.ledger_id || null,
        valid_from: form.valid_from || null,
      }),
    });
    setBusy(false);
    if (!res.ok) {
      setError(res.message);
      return;
    }
    setForm({ account_code: "", datev_account: "", label: "", ledger_id: "", valid_from: "" });
    setMessage(t("created"));
    await reload();
  }

  async function toggleActive(row: DatevMapping) {
    setError(null);
    const res = await bff<DatevMapping>(`${BASE}/${row.id}`, {
      method: "PATCH",
      body: JSON.stringify({ active: !row.active }),
    });
    if (!res.ok) {
      setError(res.message);
      return;
    }
    setRows((prev) => prev.map((r) => (r.id === row.id ? res.data : r)));
  }

  async function remove(row: DatevMapping) {
    if (!window.confirm(t("confirmDelete", { account: row.account_code }))) return;
    setError(null);
    const res = await bff<null>(`${BASE}/${row.id}`, { method: "DELETE" });
    if (!res.ok) {
      setError(res.message);
      return;
    }
    setRows((prev) => prev.filter((r) => r.id !== row.id));
  }

  async function readFile(event: React.ChangeEvent<HTMLInputElement>) {
    const file = event.target.files?.[0];
    if (!file) return;
    setCsv(await file.text());
    setPreview(null);
  }

  async function runImport(dryRun: boolean) {
    setBusy(true);
    setError(null);
    setMessage(null);
    const res = await bff<ImportResult>(`${BASE}/import`, {
      method: "POST",
      body: JSON.stringify({ content: csv, ledger_id: importLedger || null, dry_run: dryRun }),
    });
    setBusy(false);
    if (!res.ok) {
      setError(res.message);
      return;
    }
    setPreview(res.data);
    if (!dryRun) {
      setMessage(
        t("imported", {
          created: res.data.counts.created ?? 0,
          updated: res.data.counts.updated ?? 0,
          unchanged: res.data.counts.unchanged ?? 0,
        }),
      );
      setCsv("");
      await reload();
    }
  }

  async function loadReport(event: React.FormEvent) {
    event.preventDefault();
    if (!reportLedger) return;
    setBusy(true);
    setError(null);
    const params = new URLSearchParams({ ledger_id: reportLedger, start, end });
    const res = await bff<Report>(`${BASE}/report?${params.toString()}`);
    setBusy(false);
    if (!res.ok) {
      setError(res.message);
      setReport(null);
      return;
    }
    setReport(res.data);
  }

  const previewBlocked = !preview || preview.file_errors.length > 0 || (preview.counts.error ?? 0) > 0;
  const reportRows = report ? report.accounts.filter((a) => !onlyUnmapped || a.unmapped) : [];

  return (
    <div className={ui.sectionGap}>
      <p className={ui.notice}>{t("intro")}</p>
      {!canManage ? <p className={ui.help}>{t("readOnly")}</p> : null}
      {error ? (
        <p role="alert" className={ui.alert}>
          {error}
        </p>
      ) : null}
      {message ? (
        <p role="status" className={ui.success}>
          {message}
        </p>
      ) : null}

      <section className={ui.card}>
        <h2 className={ui.h2}>{t("table.title")}</h2>
        {rows.length === 0 ? (
          <p className={ui.help}>{t("table.empty")}</p>
        ) : (
          <div className="overflow-x-auto">
            <table className={ui.table}>
              <thead>
                <tr>
                  <th>{t("field.account_code")}</th>
                  <th>{t("field.datev_account")}</th>
                  <th>{t("field.label")}</th>
                  <th>{t("field.ledger")}</th>
                  <th>{t("field.valid_from")}</th>
                  <th>{t("field.active")}</th>
                  {canManage ? <th /> : null}
                </tr>
              </thead>
              <tbody>
                {rows.map((row) => (
                  <tr key={row.id}>
                    <td>{row.account_code}</td>
                    <td>{row.datev_account}</td>
                    <td>{row.label ?? ""}</td>
                    <td>{ledgerName(ledgers, row.ledger_id, t("allLedgers"))}</td>
                    <td>{formatDate(row.valid_from)}</td>
                    <td>{row.active ? t("yes") : t("no")}</td>
                    {canManage ? (
                      <td className="flex gap-2">
                        <button type="button" className={ui.buttonSm} onClick={() => void toggleActive(row)}>
                          {row.active ? t("deactivate") : t("activate")}
                        </button>
                        <button type="button" className={ui.buttonSm} onClick={() => void remove(row)}>
                          {t("delete")}
                        </button>
                      </td>
                    ) : null}
                  </tr>
                ))}
              </tbody>
            </table>
          </div>
        )}
      </section>

      {canManage ? (
        <form onSubmit={(e) => void create(e)} className={`${ui.card} grid gap-3 sm:grid-cols-3`}>
          <h2 className={`${ui.h2} sm:col-span-3`}>{t("create.title")}</h2>
          <label className="flex flex-col gap-1">
            <span className={ui.label}>{t("field.account_code")}</span>
            <input
              className={ui.input}
              required
              maxLength={32}
              value={form.account_code}
              onChange={(e) => setForm({ ...form, account_code: e.target.value })}
            />
          </label>
          <label className="flex flex-col gap-1">
            <span className={ui.label}>{t("field.datev_account")}</span>
            <input
              className={ui.input}
              required
              inputMode="numeric"
              pattern="[0-9]+"
              maxLength={16}
              value={form.datev_account}
              onChange={(e) => setForm({ ...form, datev_account: e.target.value })}
            />
          </label>
          <label className="flex flex-col gap-1">
            <span className={ui.label}>{t("field.label")}</span>
            <input className={ui.input} maxLength={200} value={form.label} onChange={(e) => setForm({ ...form, label: e.target.value })} />
          </label>
          <label className="flex flex-col gap-1">
            <span className={ui.label}>{t("field.ledger")}</span>
            <select className={ui.input} value={form.ledger_id} onChange={(e) => setForm({ ...form, ledger_id: e.target.value })}>
              <option value="">{t("allLedgers")}</option>
              {ledgers.map((l) => (
                <option key={l.id} value={l.id}>
                  {l.name}
                </option>
              ))}
            </select>
          </label>
          <label className="flex flex-col gap-1">
            <span className={ui.label}>{t("field.valid_from")}</span>
            <input className={ui.input} type="date" value={form.valid_from} onChange={(e) => setForm({ ...form, valid_from: e.target.value })} />
          </label>
          <div className="flex items-end">
            <button type="submit" className={ui.primary} disabled={busy}>
              {t("create.submit")}
            </button>
          </div>
        </form>
      ) : null}

      {canManage ? (
        <section className={`${ui.card} ${ui.sectionGap}`}>
          <h2 className={ui.h2}>{t("import.title")}</h2>
          <p className={ui.help}>{t("import.hint")}</p>
          <div className="grid gap-3 sm:grid-cols-2">
            <label className="flex flex-col gap-1">
              <span className={ui.label}>{t("import.file")}</span>
              <input type="file" accept=".csv,text/csv" className={ui.input} onChange={(e) => void readFile(e)} />
            </label>
            <label className="flex flex-col gap-1">
              <span className={ui.label}>{t("field.ledger")}</span>
              <select className={ui.input} value={importLedger} onChange={(e) => setImportLedger(e.target.value)}>
                <option value="">{t("allLedgers")}</option>
                {ledgers.map((l) => (
                  <option key={l.id} value={l.id}>
                    {l.name}
                  </option>
                ))}
              </select>
            </label>
          </div>
          <label className="flex flex-col gap-1">
            <span className={ui.label}>{t("import.content")}</span>
            <textarea
              className={ui.input}
              rows={5}
              value={csv}
              onChange={(e) => {
                setCsv(e.target.value);
                setPreview(null);
              }}
            />
          </label>
          <div className={ui.formActions}>
            <button type="button" className={ui.secondary} disabled={busy || !csv.trim()} onClick={() => void runImport(true)}>
              {t("import.preview")}
            </button>
            <button type="button" className={ui.primary} disabled={busy || previewBlocked} onClick={() => void runImport(false)}>
              {t("import.apply")}
            </button>
          </div>
          {preview ? (
            <div className={ui.sectionGap}>
              {preview.file_errors.map((fe) => (
                <p key={fe} role="alert" className={ui.alert}>
                  {fe}
                </p>
              ))}
              <p className={ui.help}>
                {t("import.summary", {
                  create: preview.counts.create ?? 0,
                  update: preview.counts.update ?? 0,
                  unchanged: preview.counts.unchanged ?? 0,
                  error: preview.counts.error ?? 0,
                })}
              </p>
              {preview.rows.length ? (
                <div className="overflow-x-auto">
                  <table className={ui.table}>
                    <thead>
                      <tr>
                        <th>{t("import.line")}</th>
                        <th>{t("field.account_code")}</th>
                        <th>{t("field.datev_account")}</th>
                        <th>{t("field.label")}</th>
                        <th>{t("field.valid_from")}</th>
                        <th>{t("import.action")}</th>
                      </tr>
                    </thead>
                    <tbody>
                      {preview.rows.map((r) => (
                        <tr key={r.line_no}>
                          <td>{r.line_no}</td>
                          <td>{r.account_code ?? ""}</td>
                          <td>
                            {r.datev_account ?? ""}
                            {r.action === "update" && r.existing_datev_account ? ` (${t("import.was")} ${r.existing_datev_account})` : ""}
                          </td>
                          <td>{r.label ?? ""}</td>
                          <td>{formatDate(r.valid_from)}</td>
                          <td>{r.action === "error" ? <span className={ui.badgeDanger}>{r.error}</span> : t(`import.actions.${r.action}`)}</td>
                        </tr>
                      ))}
                    </tbody>
                  </table>
                </div>
              ) : null}
            </div>
          ) : null}
        </section>
      ) : null}

      <section className={`${ui.card} ${ui.sectionGap}`}>
        <h2 className={ui.h2}>{t("report.title")}</h2>
        <p className={ui.help}>{t("report.hint")}</p>
        <form onSubmit={(e) => void loadReport(e)} className="grid gap-3 sm:grid-cols-4">
          <label className="flex flex-col gap-1">
            <span className={ui.label}>{t("field.ledger")}</span>
            <select className={ui.input} required value={reportLedger} onChange={(e) => setReportLedger(e.target.value)}>
              {ledgers.length === 0 ? <option value="">{t("report.noLedgers")}</option> : null}
              {ledgers.map((l) => (
                <option key={l.id} value={l.id}>
                  {l.name}
                </option>
              ))}
            </select>
          </label>
          <label className="flex flex-col gap-1">
            <span className={ui.label}>{t("report.start")}</span>
            <input className={ui.input} type="date" required value={start} onChange={(e) => setStart(e.target.value)} />
          </label>
          <label className="flex flex-col gap-1">
            <span className={ui.label}>{t("report.end")}</span>
            <input className={ui.input} type="date" required value={end} onChange={(e) => setEnd(e.target.value)} />
          </label>
          <div className="flex items-end">
            <button type="submit" className={ui.secondary} disabled={busy || !reportLedger}>
              {t("report.run")}
            </button>
          </div>
        </form>
        {report ? (
          <div className={ui.sectionGap}>
            <p className={report.used_unmapped_count > 0 ? ui.alert : ui.success} role="status">
              {t("report.summary", { unmapped: report.unmapped_count, used: report.used_unmapped_count })}
            </p>
            <label className="flex items-center gap-2 text-sm">
              <input type="checkbox" checked={onlyUnmapped} onChange={(e) => setOnlyUnmapped(e.target.checked)} />
              {t("report.onlyUnmapped")}
            </label>
            <div className="overflow-x-auto">
              <table className={ui.table}>
                <thead>
                  <tr>
                    <th>{t("field.account_code")}</th>
                    <th>{t("report.accountName")}</th>
                    <th>{t("field.datev_account")}</th>
                    <th>{t("report.lines")}</th>
                    <th>{t("report.period")}</th>
                    <th>{t("report.status")}</th>
                  </tr>
                </thead>
                <tbody>
                  {reportRows.map((a) => (
                    <tr key={a.account_id}>
                      <td>{a.account_code}</td>
                      <td>{a.account_name}</td>
                      <td>{a.datev_account ?? ""}</td>
                      <td>{a.lines_in_period}</td>
                      <td>{a.first_booking_date ? `${formatDate(a.first_booking_date)} ${t("report.to")} ${formatDate(a.last_booking_date)}` : ""}</td>
                      <td>
                        {a.unmapped ? (
                          <span className={a.lines_in_period ? ui.badgeDanger : ui.badgeWarning}>{a.reason ?? t("report.unmapped")}</span>
                        ) : (
                          <span className={ui.badgeSuccess}>{t("report.mapped")}</span>
                        )}
                      </td>
                    </tr>
                  ))}
                </tbody>
              </table>
            </div>
          </div>
        ) : null}
      </section>
    </div>
  );
}
